// 比较两个浮点数数组是否近似相等（允许 1e-6 相对误差）
static bool approx_equal(const float *x, const float *y) {
    for (int i = 0; i < VECTOR_SIZE; ++i) {
        float diff = fabsf(x[i] - y[i]);
        float tol = 1e-6f * fmaxf(fabsf(x[i]), fabsf(y[i]));
        if (diff > tol && diff > 1e-7f) {
            return false;
        }
    }
    return true;
}

