static bool is_vmx_and_hypervisor() {
    uint32_t eax, ebx, ecx, edx;
    __asm__ volatile("cpuid"
                     : "=a"(eax), "=b"(ebx), "=c"(ecx), "=d"(edx)
                     : "a"(1), "c"(0));
    bool vmx = (ecx & (1 << 5)) != 0;
    bool hypervisor = (ecx & (1 << 31)) != 0;
    return vmx && hypervisor;
}

